 {page===9&&<><div className="two-col"><Card title="Organizational structure" sub="Brands, locations and platform accounts"><div className="config-list">{['brands','locations','accounts'].map(k=><div key={k}><h4>{k==='brands'?'Brands':k}</h4>{(data.config as any)[k].map((v:any)=><Badge key={typeof v==='string'?v:v.name} kind="neutral">{typeof v==='string'?v:`${v.name} · ${v.platform}`}</Badge>)}</div>)}</div><button className="button primary" onClick={()=>setConfigEdit(JSON.stringify(data.config,null,2))}><Settings size={16}/> Edit configuration</button></Card><Card title="Workspace & data policy" sub="Public access"><div className="insight-list"><div><h3>Manual-first collection</h3><p>No Meta, Instagram or Workvivo API connection is required. CSV, Excel and manual entry are the primary ingestion paths.</p></div><div><h3>Account-aware reporting</h3><p>Shared Facebook accounts can serve multiple brands and locations. Followers remain account-level snapshots.</p></div><div><h3>Public access</h3><p>Anyone with the URL can view the dashboards and upload updated reports. Changes update the shared public dataset.</p></div></div></Card></div><Card title="Audit trail" sub="Latest 100 live changes. Record deletions remove linked stakeholder interactions."><div className="table-wrap"><table><thead><tr><th>Time (Singapore)</th><th>Action</th><th>Record</th><th>Update source</th></tr></thead><tbody>{audit.map(a=><tr key={a.id}><td>{new Date(a.date).toLocaleString('en-SG',{timeZone:'Asia/Singapore'})}</td><td>{a.action}</td><td>{a.record_id}</td><td>{a.actor}</td></tr>)}</tbody></table>{!audit.length&&<p className="empty">Live changes will appear here.</p>}</div></Card></>}
