 {importRows&&<div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label="Review Excel import"><div className="modal-head"><div><h2>{importInfo?.format||'Review Excel import'}</h2><p>{importRows.reduce((n,b)=>n+b.items.length,0)} validated records across {importRows.length} record groups. Your workbook will update the shared database.</p></div><button className="icon-button" aria-label="Cancel import" disabled={busy} onClick={()=>setImportRows(null)}><X size={20}/></button></div>{importInfo?.startYear&&<label className="field report-year">Follower report starting year<select disabled={busy} value={importInfo.startYear} onChange={e=>changeReportYear(Number(e.target.value))}>{Array.from({length:201},(_,i)=>1900+i).map(y=><option key={y}>{y}</option>)}</select><small>Years are absent from Month labels. The first year is inferred from post dates and can be corrected here.</small></label>}{!!importInfo?.warnings.length&&<div className="import-warnings"><strong>Review before importing</strong><ul>{importInfo.warnings.map(w=><li key={w}>{w}</li>)}</ul></div>}{importRows.map(b=><div key={b.kind}><h3 className="import-group-title">{b.kind} · {b.items.length} records · {b.items.filter(r=>(data as any)[b.kind].some((v:any)=>v.id===r.id)).length} updates</h3><div className="table-wrap"><table><thead><tr><th>Record</th><th>Date</th><th>ID</th></tr></thead><tbody>{b.items.slice(0,5).map(r=><tr key={r.id}><td>{r.title||r.stakeholder||r.objectiveId||r.account}</td><td>{r.date||'—'}</td><td>{r.id}</td></tr>)}</tbody></table></div></div>)}<div className="method-note"><Info size={17}/><span>Preview shows the first 5 records in each group. The complete workbook is validated and saved together. Missing standard-report metrics stay unavailable; missing topics and features are not inferred from titles.</span></div>{error&&<div className="error">{error}</div>}<div className="modal-actions"><button className="button" disabled={busy} onClick={()=>setImportRows(null)}>Cancel</button><button className="button primary" disabled={busy} onClick={commitImport}>{busy?'Importing…':'Confirm import'}</button></div></section></div>}
 {configEdit&&<div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label="Edit configuration"><div className="modal-head"><div><h2>Workspace configuration</h2><p>Add brands, locations, accounts, topics and stakeholders. Referenced values cannot be removed.</p></div><button className="icon-button" aria-label="Close configuration" onClick={()=>setConfigEdit('')}><X size={20}/></button></div>{(()=>{const c:Config=JSON.parse(configEdit);const update=(next:Config)=>setConfigEdit(JSON.stringify(next));return <div className="configuration-form"><div className="form-grid">{(['brands','locations','topics','types'] as const).map(k=><label className="field" key={k}>{k==='brands'?'Brands':k.charAt(0).toUpperCase()+k.slice(1)} ? one per line<textarea rows={5} value={c[k].join('\n')} onChange={e=>update({...c,[k]:e.target.value.split('\n')})}/></label>)}</div>{(['accounts','stakeholders'] as const).map(k=><div className="config-group" key={k}><h3>{k==='accounts'?'Platform accounts':'Strategic stakeholders'}</h3>{c[k].map((v:any,i)=><div className="config-row" key={i}><input aria-label={k==='accounts'?'Account name':'Stakeholder name'} value={v.name} onChange={e=>update({...c,[k]:c[k].map((a,j)=>j===i?{...a,name:e.target.value}:a)})}/><select aria-label={k==='accounts'?'Account platform':'Stakeholder sector'} value={k==='accounts'?v.platform:v.sector} onChange={e=>update({...c,[k]:c[k].map((a,j)=>j===i?{...a,[k==='accounts'?'platform':'sector']:e.target.value}:a)})}>{(k==='accounts'?['Facebook','Instagram','Workvivo']:['Government','Social Sector','Partners']).map(o=><option key={o}>{o}</option>)}</select>{k==='accounts'&&<select aria-label="Account brand attribution" value={v.brand||''} onChange={e=>update({...c,accounts:c.accounts.map((a,j)=>j===i?{...a,brand:e.target.value}:a)})}><option value="">Shared audience</option>{c.brands.map(p=><option key={p}>{p}</option>)}</select>}<button className="icon-button danger" aria-label="Remove configuration entry" onClick={()=>update({...c,[k]:c[k].filter((_,j)=>j!==i)})}><Trash2 size={15}/></button></div>)}<button className="text-button" onClick={()=>update({...c,[k]:[...c[k],k==='accounts'?{name:'New account',platform:'Facebook'}:{name:'New stakeholder',sector:'Partners'}]})}><Plus size={15}/> Add {k==='accounts'?'account':'stakeholder'}</button></div>)}</div>})()}{error&&<div className="error">{error}</div>}<div className="modal-actions"><button className="button" onClick={()=>setConfigEdit('')}>Cancel</button><button className="button primary" disabled={busy} onClick={async()=>{try{const c=JSON.parse(configEdit);if(await mutate({action:'config',items:c}))setConfigEdit('')}catch(e:any){setError(e.message)}}}>Save configuration</button></div></section></div>}
